use std::collections::HashMap;

// Simplified O(1)-ish LRU: HashMap + recency re-insertion.
pub struct LRUCache {
    capacity: usize,
    items: HashMap<i32, i32>,
    recency: Vec<i32>,   // front = most recent
}

impl LRUCache {
    pub fn new(capacity: i32) -> Self {
        LRUCache { capacity: capacity as usize, items: HashMap::new(), recency: Vec::new() }
    }

    pub fn get(&mut self, key: i32) -> i32 {
        match self.items.get(&key) {
            Some(&v) => {
                self.recency.retain(|&k| k != key);
                self.recency.insert(0, key);
                v
            }
            None => -1,
        }
    }

    pub fn put(&mut self, key: i32, value: i32) {
        if !self.items.contains_key(&key) {
            self.recency.retain(|&k| k != key);
            self.recency.insert(0, key);
        }
        self.items.insert(key, value);
        if self.items.len() > self.capacity {
            if let Some(oldest) = self.recency.pop() {
                self.items.remove(&oldest);
            }
        }
    }
}

