type item struct {
    node string
    dist int
}
type pq []item

func (p pq) Len() int            { return len(p) }
func (p pq) Less(i, j int) bool  { return p[i].dist < p[j].dist }
func (p pq) Swap(i, j int)       { p[i], p[j] = p[j], p[i] }
func (p *pq) Push(x any)         { *p = append(*p, x.(item)) }
func (p *pq) Pop() any {
    old := *p
    n := len(old)
    v := old[n-1]
    *p = old[:n-1]
    return v
}

func Dijkstra(graph map[string][]item, start string) map[string]int {
    dist := map[string]int{}
    for node := range graph {
        dist[node] = 1 << 60
    }
    dist[start] = 0
    h := &pq{{start, 0}}
    heap.Init(h)
    for h.Len() > 0 {
        cur := heap.Pop(h).(item)
        if cur.dist > dist[cur.node] {
            continue
        }
        for _, edge := range graph[cur.node] {
            if nd := cur.dist + edge.dist; nd < dist[edge.node] {
                dist[edge.node] = nd
                heap.Push(h, item{edge.node, nd})
            }
        }
    }
    return dist
}

